import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { updateCar } from "../../services/ApiCar";

export default function UpdateVoiture() {
  const navigate = useNavigate();
  const { state } = useLocation();
  const { car } = state || {};
  
  const [formData, setFormData] = useState({
    matricule: car?.matricule || "",
    model: car?.model || "",
    marque: car?.marque || "",
    prix_jour: car?.prix_jour || "",
    disponible: car?.disponible || false,
    voiture_image: null
  });
  const [previewImage, setPreviewImage] = useState(car?.voiture_image || "");
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === "checkbox" ? checked : value
    });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFormData({ ...formData, voiture_image: file });
      setPreviewImage(URL.createObjectURL(file));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const data = new FormData();
      Object.keys(formData).forEach(key => {
        if (formData[key] !== null) {
          data.append(key, formData[key]);
        }
      });

      await updateCar(data, car._id);
      navigate("/admin/cardvoiture", { state: { refresh: true } });
    } catch (error) {
      console.error("Erreur:", error);
      alert("Erreur lors de la mise à jour");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="bg-white rounded-lg shadow-md p-6">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold">Modifier la voiture</h2>
          <button
            onClick={() => navigate("/admin/Voiture")}
            className="bg-gray-500 hover:bg-gray-600 text-white px-4 py-2 rounded"
          >
            Retour
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium mb-1">Matricule</label>
              <input
                type="text"
                name="matricule"
                value={formData.matricule}
                onChange={handleChange}
                className="w-full px-3 py-2 border rounded"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-1">Modèle</label>
              <input
                type="text"
                name="model"
                value={formData.model}
                onChange={handleChange}
                className="w-full px-3 py-2 border rounded"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-1">Marque</label>
              <input
                type="text"
                name="marque"
                value={formData.marque}
                onChange={handleChange}
                className="w-full px-3 py-2 border rounded"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium mb-1">Prix par jour (€)</label>
              <input
                type="number"
                name="prix_jour"
                value={formData.prix_jour}
                onChange={handleChange}
                className="w-full px-3 py-2 border rounded"
                required
                min="0"
              />
            </div>

            <div className="flex items-center">
              <input
                type="checkbox"
                name="disponible"
                checked={formData.disponible}
                onChange={handleChange}
                className="h-4 w-4 text-blue-600 rounded"
              />
              <label className="ml-2 text-sm font-medium">Disponible</label>
            </div>

            <div>
              <label className="block text-sm font-medium mb-1">Image</label>
              {previewImage && (
                <div className="mb-2">
                  <img 
                    src={previewImage} 
                    alt="Preview" 
                    className="h-32 object-contain"
                  />
                </div>
              )}
              <input
                type="file"
                name="voiture_image"
                onChange={handleFileChange}
                className="w-full px-3 py-2 border rounded"
                accept="image/*"
              />
            </div>
          </div>

          <div className="flex justify-end">
            <button
              type="submit"
              disabled={isLoading}
              className={`${
                isLoading ? "bg-gray-500" : "bg-blue-500 hover:bg-blue-600"
              } text-white px-6 py-2 rounded shadow`}
            >
              {isLoading ? "Enregistrement..." : "Mettre à jour"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
